<?php require 'includes/bootstrap.php';$items=cartDetails($pdo);if(!$items){header('Location: cart.php');exit;}$total=array_sum(array_column($items,'line_total'));$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$name=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');$email=trim($_POST['email']??'');$address=trim($_POST['address']??'');$notes=trim($_POST['notes']??'');if(!$name||!$phone||!$address)$error='Please complete all required fields.';elseif($email&&!filter_var($email,FILTER_VALIDATE_EMAIL))$error='Please enter a valid email address.';elseif(strlen($name)>120||strlen($phone)>30||strlen($email)>150)$error='Some details are too long.';else{try{$pdo->beginTransaction();$fresh=[];$total=0;foreach($items as $item){$s=$pdo->prepare('SELECT * FROM products WHERE id=? FOR UPDATE');$s->execute([$item['id']]);$p=$s->fetch();if(!$p||$p['stock']<$item['quantity'])throw new Exception('Some products are no longer in stock. Please update your cart.');$fresh[]=['p'=>$p,'qty'=>$item['quantity']];$total+=(float)$p['price']*$item['quantity'];}$s=$pdo->prepare('INSERT INTO orders(customer_name,phone,email,delivery_address,notes,subtotal) VALUES(?,?,?,?,?,?)');$s->execute([$name,$phone,$email?:null,$address,$notes?:null,$total]);$orderId=$pdo->lastInsertId();foreach($fresh as $entry){$p=$entry['p'];$qty=$entry['qty'];$pdo->prepare('INSERT INTO order_items(order_id,product_id,product_name,quantity,unit_price) VALUES(?,?,?,?,?)')->execute([$orderId,$p['id'],$p['name'],$qty,$p['price']]);$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=?')->execute([$qty,$p['id']]);}$pdo->commit();unset($_SESSION['cart']);$_SESSION['last_order']=$orderId;header('Location: success.php');exit;}catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();$error=$ex->getMessage();}}}$pageTitle='Checkout | AquaPure';require 'includes/header.php';?><section class="container page"><span class="eyebrow">ALMOST THERE</span><h1>Complete your order</h1><p class="muted">Enter your details so we can arrange your water delivery.</p><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><div class="cart-layout"><form class="checkout-form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><h2>Delivery details</h2><label>Full name *<input name="name" maxlength="120" required value="<?=e($_POST['name']??'')?>" placeholder="Your full name"></label><label>Phone number *<input name="phone" maxlength="30" required value="<?=e($_POST['phone']??'')?>" placeholder="080..." type="tel"></label><label>Email (optional)<input name="email" maxlength="150" type="email" value="<?=e($_POST['email']??'')?>" placeholder="you@example.com"></label><label>Delivery address *<textarea name="address" required rows="3" placeholder="Street, area, city"><?=e($_POST['address']??'')?></textarea></label><label>Order notes (optional)<textarea name="notes" rows="3" placeholder="Delivery instructions"><?=e($_POST['notes']??'')?></textarea></label><button class="btn full">Place Order →</button><p class="muted">No online payment is collected. The team will contact you to confirm delivery and payment.</p></form><aside class="summary"><h2>Your order</h2><?php foreach($items as $p):?><div class="total-row"><span><?=e($p['name'])?> × <?=$p['quantity']?></span><strong><?=money($p['line_total'])?></strong></div><?php endforeach;?><div class="total-row grand"><span>Items total</span><strong><?=money($total)?></strong></div><p class="muted">Delivery fee, if any, is confirmed after ordering.</p></aside></div></section><?php require 'includes/footer.php';?>
